  /*************************************************************************/
  /*                                                                       */
  /* The macro ALL_POINTS is used in `ft_var_readpackedpoints'.  It        */
  /* indicates that there is a delta for every point without needing to    */
  /* enumerate all of them.                                                */
  /*                                                                       */

  /* ensure that value `0' has the same width as a pointer */
#define ALL_POINTS  (FT_UShort*)~(FT_PtrDist)0


#define GX_PT_POINTS_ARE_WORDS      0x80U
#define GX_PT_POINT_RUN_COUNT_MASK  0x7FU


  /*************************************************************************/
  /*                                                                       */
  /* <Function>                                                            */
  /*    ft_var_readpackedpoints                                            */
  /*                                                                       */
  /* <Description>                                                         */
  /*    Read a set of points to which the following deltas will apply.     */
  /*    Points are packed with a run length encoding.                      */
  /*                                                                       */
  /* <Input>                                                               */
  /*    stream    :: The data stream.                                      */
  /*                                                                       */
  /*    size      :: The size of the table holding the data.               */
  /*                                                                       */
  /* <Output>                                                              */
  /*    point_cnt :: The number of points read.  A zero value means that   */
  /*                 all points in the glyph will be affected, without     */
  /*                 enumerating them individually.                        */
  /*                                                                       */
  /* <Return>                                                              */
  /*    An array of FT_UShort containing the affected points or the        */
  /*    special value ALL_POINTS.                                          */
  /*                                                                       */
  static FT_UShort*
  ft_var_readpackedpoints( FT_Stream  stream,
                           FT_ULong   size,
                           FT_UInt   *point_cnt )
  {
    FT_UShort *points = NULL;
    FT_UInt    n;
    FT_UInt    runcnt;
    FT_UInt    i, j;
    FT_UShort  first;
    FT_Memory  memory = stream->memory;
    FT_Error   error  = FT_Err_Ok;

    FT_UNUSED( error );


    *point_cnt = 0;

    n = FT_GET_BYTE();
    if ( n == 0 )
      return ALL_POINTS;

    if ( n & GX_PT_POINTS_ARE_WORDS )
    {
      n  &= GX_PT_POINT_RUN_COUNT_MASK;
      n <<= 8;
      n  |= FT_GET_BYTE();
    }

    if ( n > size )
    {
      FT_TRACE1(( "ft_var_readpackedpoints: number of points too large\n" ));
      return NULL;
    }

    /* in the nested loops below we increase `i' twice; */
    /* it is faster to simply allocate one more slot    */
    /* than to add another test within the loop         */
    if ( FT_NEW_ARRAY( points, n + 1 ) )
      return NULL;

    *point_cnt = n;

    first = 0;
    i     = 0;
    while ( i < n )
    {
      runcnt = FT_GET_BYTE();
      if ( runcnt & GX_PT_POINTS_ARE_WORDS )
      {
        runcnt     &= GX_PT_POINT_RUN_COUNT_MASK;
        first      += FT_GET_USHORT();
        points[i++] = first;

        /* first point not included in run count */
        for ( j = 0; j < runcnt; j++ )
        {
          first      += FT_GET_USHORT();
          points[i++] = first;
          if ( i >= n )
            break;
        }
      }
      else
      {
        first      += FT_GET_BYTE();
        points[i++] = first;

        for ( j = 0; j < runcnt; j++ )
        {
          first      += FT_GET_BYTE();
          points[i++] = first;
          if ( i >= n )
            break;
        }
      }
    }

    return points;
  }


#define GX_DT_DELTAS_ARE_ZERO       0x80U
#define GX_DT_DELTAS_ARE_WORDS      0x40U
#define GX_DT_DELTA_RUN_COUNT_MASK  0x3FU


  /*************************************************************************/
  /*                                                                       */
  /* <Function>                                                            */
  /*    ft_var_readpackeddeltas                                            */
  /*                                                                       */
  /* <Description>                                                         */
  /*    Read a set of deltas.  These are packed slightly differently than  */
  /*    points.  In particular there is no overall count.                  */
  /*                                                                       */
  /* <Input>                                                               */
---

  /* the validity of the `fvar' header data was already checked */
  /* in function `sfnt_init_face'                               */
  if ( FT_STREAM_READ_FIELDS( fvar_fields, &fvar_head ) )
    goto Exit;

  usePsName = FT_BOOL( fvar_head.instanceSize ==
                       6 + 4 * fvar_head.axisCount );

  FT_TRACE2(( "loaded\n" ));

  FT_TRACE5(( "number of GX style axes: %d\n", fvar_head.axisCount ));

  if ( FT_NEW( face->blend ) )
    goto Exit;

  /* `num_instances' holds the number of all named instances, */
  /* including the default instance which might be missing    */
  /* in fvar's table of named instances                       */
  num_instances = face->root.style_flags >> 16;

  /* cannot overflow 32-bit arithmetic because of the size limits */
  /* used in the `fvar' table validity check in `sfnt_init_face'  */
  face->blend->mmvar_len =
    sizeof ( FT_MM_Var ) +
    fvar_head.axisCount * sizeof ( FT_Var_Axis ) +
    num_instances * sizeof ( FT_Var_Named_Style ) +
    num_instances * fvar_head.axisCount * sizeof ( FT_Fixed ) +
    5 * fvar_head.axisCount;

  if ( FT_ALLOC( mmvar, face->blend->mmvar_len ) )
    goto Exit;
  face->blend->mmvar = mmvar;

  /* set up pointers and offsets into the `mmvar' array; */
  /* the data gets filled in later on                    */

  mmvar->num_axis =
    fvar_head.axisCount;
  mmvar->num_designs =
    ~0U;                   /* meaningless in this context; each glyph */
                           /* may have a different number of designs  */
                           /* (or tuples, as called by Apple)         */
  mmvar->num_namedstyles =
    num_instances;
  mmvar->axis =
    (FT_Var_Axis*)&( mmvar[1] );
  mmvar->namedstyle =
    (FT_Var_Named_Style*)&( mmvar->axis[fvar_head.axisCount] );

  next_coords =
    (FT_Fixed*)&( mmvar->namedstyle[num_instances] );
  for ( i = 0; i < num_instances; i++ )
  {
    mmvar->namedstyle[i].coords  = next_coords;
    next_coords                 += fvar_head.axisCount;
  }

  next_name = (FT_String*)next_coords;
  for ( i = 0; i < fvar_head.axisCount; i++ )
  {
    mmvar->axis[i].name  = next_name;
    next_name           += 5;
  }

  /* now fill in the data */

  if ( FT_STREAM_SEEK( fvar_start + fvar_head.offsetToData ) )
    goto Exit;

  a = mmvar->axis;
  for ( i = 0; i < fvar_head.axisCount; i++ )
  {
    GX_FVar_Axis  axis_rec;


    if ( FT_STREAM_READ_FIELDS( fvaraxis_fields, &axis_rec ) )
      goto Exit;
    a->tag     = axis_rec.axisTag;
    a->minimum = axis_rec.minValue;
    a->def     = axis_rec.defaultValue;
    a->maximum = axis_rec.maxValue;
    a->strid   = axis_rec.nameID;

    a->name[0] = (FT_String)(   a->tag >> 24 );
    a->name[1] = (FT_String)( ( a->tag >> 16 ) & 0xFF );
    a->name[2] = (FT_String)( ( a->tag >>  8 ) & 0xFF );
    a->name[3] = (FT_String)( ( a->tag       ) & 0xFF );
    a->name[4] = '\0';

    if ( a->minimum > a->def ||
         a->def > a->maximum )
    {
      FT_TRACE2(( "TT_Get_MM_Var:"
                  " invalid \"%s\" axis record; disabling\n",
                  a->name ));

      a->minimum = a->def;
      a->maximum = a->def;
    }

    FT_TRACE5(( "  \"%s\": minimum=%.5f, default=%.5f, maximum=%.5f\n",
                a->name,
                a->minimum / 65536.0,
                a->def / 65536.0,
                a->maximum / 65536.0 ));

    a++;
  }

  FT_TRACE5(( "\n" ));

  /* named instance coordinates are stored as design coordinates; */
  /* we have to convert them to normalized coordinates also       */
  if ( FT_NEW_ARRAY( face->blend->normalized_stylecoords,
                     fvar_head.axisCount * num_instances ) )
    goto Exit;

  if ( fvar_head.instanceCount && !face->blend->avar_checked )
    ft_var_load_avar( face );

  ns  = mmvar->namedstyle;
  nsc = face->blend->normalized_stylecoords;
  for ( i = 0; i < fvar_head.instanceCount; i++, ns++ )
  {
    /* PostScript names add 2 bytes to the instance record size */
    if ( FT_FRAME_ENTER( ( usePsName ? 6L : 4L ) +
                         4L * fvar_head.axisCount ) )
      goto Exit;

    ns->strid       =    FT_GET_USHORT();
    (void) /* flags = */ FT_GET_USHORT();

    c = ns->coords;
    for ( j = 0; j < fvar_head.axisCount; j++, c++ )
      *c = FT_GET_LONG();

    if ( usePsName )
      ns->psid = FT_GET_USHORT();

    ft_var_to_normalized( face,
                          fvar_head.axisCount,
                          ns->coords,
                          nsc );
    nsc += fvar_head.axisCount;

    FT_FRAME_EXIT();
  }

  if ( num_instances != fvar_head.instanceCount )
  {
    SFNT_Service  sfnt = (SFNT_Service)face->sfnt;

    FT_Int  found, win, apple;


    /* the default instance is missing in array the   */
    /* of named instances; try to synthesize an entry */
    found = sfnt->get_name_id( face,
                               TT_NAME_ID_TYPOGRAPHIC_SUBFAMILY,
                               &win,
                               &apple );
    if ( !found )
      found = sfnt->get_name_id( face,
                                 TT_NAME_ID_FONT_SUBFAMILY,
                                 &win,
                                 &apple );

    if ( found )
    {
      FT_Int  strid = win >= 0 ? win : apple;


      found = sfnt->get_name_id( face,
                                 TT_NAME_ID_PS_NAME,
                                 &win,
                                 &apple );
      if ( found )
      {
        FT_Int  psid = win >= 0 ? win : apple;


        FT_TRACE5(( "TT_Get_MM_Var:"
                    " Adding default instance to named instances\n" ));

        ns = &mmvar->namedstyle[fvar_head.instanceCount];

        ns->strid = strid;
        ns->psid  = psid;

        a = mmvar->axis;
        c = ns->coords;
        for ( j = 0; j < fvar_head.axisCount; j++, a++, c++ )
          *c = a->def;
      }
    }
  }

  ft_var_load_mvar( face );
}

/* fill the output array if requested */

if ( master )
{
  FT_UInt  n;


  if ( FT_ALLOC( mmvar, face->blend->mmvar_len ) )
    goto Exit;
  FT_MEM_COPY( mmvar, face->blend->mmvar, face->blend->mmvar_len );

  mmvar->axis =
    (FT_Var_Axis*)&( mmvar[1] );
  mmvar->namedstyle =
    (FT_Var_Named_Style*)&( mmvar->axis[mmvar->num_axis] );
  next_coords =
    (FT_Fixed*)&( mmvar->namedstyle[mmvar->num_namedstyles] );

  for ( n = 0; n < mmvar->num_namedstyles; n++ )
  {
    mmvar->namedstyle[n].coords  = next_coords;
    next_coords                 += mmvar->num_axis;
  }

  a         = mmvar->axis;
  next_name = (FT_String*)next_coords;

